import random
import math

def generate_disjointness_matrix(n):
    M = [[0] * n for _ in range(n)]
    for i in range(n):
        for j in range(i + 1, n):
            if random.choice([True, False]):
                M[i][j] = 1
                M[j][i] = 1
    return M

def matrix_rank(M):
    m, n = len(M), len(M[0])
    rank = 0
    for i in range(m):
        pivot_row = None
        for j in range(i, m):
            if M[j][i] != 0:
                pivot_row = j
                break
        if pivot_row is None:
            continue
        rank += 1
        for j in range(n):
            M[pivot_row][j], M[i][j] = M[i][j], M[pivot_row][j]
        for j in range(m):
            if j != i and M[j][i] != 0:
                factor = M[j][i] / M[i][i]
                for k in range(n):
                    M[j][k] -= factor * M[i][k]
    return rank

def run_trial(seed: int) -> dict:
    random.seed(seed)
    n_values = [5, 10, 15, 20, 30, 40]
    c = 0.25
    total_metric_value = 0
    instances_tested = 0
    conjecture_holds = True
    counterexample = ""

    for n in n_values:
        M = generate_disjointness_matrix(n)
        rank = matrix_rank(M)
        secant_dimension = min(rank + 1, n)
        total_metric_value += secant_dimension
        instances_tested += 1

        if secant_dimension < c * n:
            conjecture_holds = False
            counterexample = f"n={n}, rank={rank}, dim(σ(M))={secant_dimension}"

